"""PB-01 user checks: Sharadar on the researcher's own key (api.sharadar.com, not Nasdaq Data Link).

Run in order (see README):  python3 probe.py bulk   then   python3 probe.py checks   then   python3 probe.py update
Raw tables stay in out/ (licensed data, never committed). Evidence holds counts, shares and enums only.
"""
from __future__ import annotations

import bisect
import csv
import datetime as dt
import io
import json
import os
import sys
import time
import urllib.error
import urllib.request
import zipfile
from collections import Counter, defaultdict

from probe_kit import load_env, private, record, save_private, write_evidence

BASE = os.environ.get("SHARADAR_BASE_URL", "https://api.sharadar.com/v1.0")
START = "2005-01-03"
TABLES = ("tickers", "actions", "sp500", "stocks")
DELIST = {"delisted", "voluntarydelisting", "regulatorydelisting", "bankruptcyliquidation",
          "acquisitionby", "mergerfrom"}
ACQ_VALUE = {"acquisitioncash", "acquisitionstock"}
calls = Counter()


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, *a, **k):
        return None


def request(path: str, params: dict, follow: bool = True) -> tuple[int, bytes, str]:
    url = f"{BASE}{path}?" + "&".join(f"{k}={v}" for k, v in params.items())
    req = urllib.request.Request(url, headers={"x-api-key": os.environ["SHARADAR_API_KEY"]})
    opener = urllib.request.build_opener() if follow else urllib.request.build_opener(NoRedirect)
    try:
        with opener.open(req, timeout=600) as r:
            calls[r.status] += 1
            return r.status, r.read(), ""
    except urllib.error.HTTPError as e:
        calls[e.code] += 1
        if e.code in (301, 302, 303, 307):
            return e.code, b"", e.headers.get("Location", "")
        sys.exit(f"HTTP {e.code} on {path}")


def rows(table: str):
    """Rows of a bulk-downloaded table, as dicts, streamed from out/."""
    path = private(f"{table}.csv")
    with open(path, newline="") as f:
        yield from csv.DictReader(f)


# ---- step 1: bulk download (C8) ----

def c8_bulk() -> None:
    sizes, t0 = {}, time.time()
    for table in TABLES:
        status, _, location = request(f"/data/{table}", {"years": "full", "format": "csv"}, follow=False)
        if not location:
            sys.exit(f"{table}: expected a 302 to a bulk file, got {status}")
        with urllib.request.urlopen(location, timeout=3600) as r:  # pre-signed URL: no key header
            blob = r.read()
        if blob[:2] == b"PK":
            with zipfile.ZipFile(io.BytesIO(blob)) as z:
                blob = z.read(z.namelist()[0])
        private(f"{table}.csv").write_bytes(blob)
        os.chmod(private(f"{table}.csv"), 0o600)
        sizes[table] = round(len(blob) / 1e6)
    minutes = round((time.time() - t0) / 60, 1)
    record("C8", {"minutes": minutes, "mb": sizes, "http": dict(calls)}, passed=minutes <= 60)


# ---- step 2: coverage checks on the bulk files (C3-C7) ----

def membership() -> tuple[dict, list]:
    """Intervals per sp500 ticker from added/removed events, and the quarterly 'historical' snapshots."""
    events, snaps = [], defaultdict(set)
    for r in rows("sp500"):
        if r["action"] in ("added", "removed"):
            events.append((r["date"], r["action"], r["ticker"]))
        elif r["action"] in ("historical", "current"):
            snaps[r["date"]].add(r["ticker"])
    events.sort()
    intervals = defaultdict(list)
    for d, action, t in events:
        if action == "added":
            intervals[t].append([d, None])
        elif intervals[t] and intervals[t][-1][1] is None:
            intervals[t][-1][1] = d
        else:
            intervals[t].append([START, d])  # member since before the first event
    current = snaps[max(snaps)] if snaps else set()
    for t in current:
        if t not in intervals:
            intervals[t].append([START, None])
    return intervals, sorted(snaps.items())


def members_on(intervals: dict, day: str) -> set:
    return {t for t, spans in intervals.items() for a, b in spans if a <= day and (b is None or day < b)}


def c3_membership(intervals: dict, snaps: list) -> None:
    actions = Counter(r["action"] for r in rows("sp500"))
    first = min((d for d, _ in snaps), default=None)
    agree, counts = [], {}
    for day, tickers in snaps:
        if day < START:
            continue
        rebuilt = members_on(intervals, day)
        agree.append(len(rebuilt & tickers) / max(len(tickers), 1))
    for day in ("2005-01-03", "2008-09-15", "2015-06-30", "2020-03-16"):
        counts[day] = len(members_on(intervals, day))
    ok = (first is not None and first <= START and min(agree, default=0) >= 0.99
          and all(495 <= n <= 510 for n in counts.values()))
    record("C3", {"actions": dict(actions), "first_snapshot": first[:7] if first else None,
                  "snapshots_checked": len(agree), "min_agreement": round(min(agree, default=0), 4),
                  "members_on": counts}, passed=ok)


def ticker_map() -> dict:
    """ticker -> [(firstpricedate, lastpricedate, permaticker, isdelisted)] from tickers (SEP rows)."""
    out = defaultdict(list)
    for r in rows("tickers"):
        if r["table"] != "SEP":
            continue
        names = {r["ticker"], *(r["relatedtickers"] or "").split()}
        for n in names:
            out[n].append((r["firstpricedate"], r["lastpricedate"], r["permaticker"], r["isdelisted"]))
    return out


def c4_mapping(intervals: dict, tmap: dict) -> dict:
    """Map each membership span to exactly one permaticker live on its start date."""
    mapped, unmapped, ambiguous = {}, [], []
    for t, spans in intervals.items():
        for a, b in spans:
            if b is not None and b <= START:
                continue
            day = max(a, START)
            live = {p for f, l, p, _ in tmap.get(t, []) if f and f <= day and (not l or day <= l)}
            if len(live) == 1:
                mapped.setdefault(live.pop(), []).append((day, b))
            elif live:
                ambiguous.append(t)
            else:
                unmapped.append(t)
    total = sum(len(v) for v in mapped.values()) + len(unmapped) + len(ambiguous)
    share = sum(len(v) for v in mapped.values()) / max(total, 1)
    save_private("unmapped.json", {"unmapped": unmapped, "ambiguous": ambiguous})
    record("C4", {"spans": total, "mapped_share": round(share, 4), "unmapped": len(unmapped),
                  "ambiguous": len(ambiguous)}, passed=share >= 0.99)
    return mapped


def load_prices(perma: set, tmap: dict) -> dict:
    """{permaticker: {date: (closeunadj, closeadj)}} for member securities from 2005 on."""
    by_ticker = {}
    for t, lst in tmap.items():
        for f, l, p, _ in lst:
            if p in perma:
                by_ticker.setdefault(t, []).append((f, l, p))
    px = defaultdict(dict)
    for r in rows("stocks"):
        if r["date"] < START or r["ticker"] not in by_ticker:
            continue
        for f, l, p in by_ticker[r["ticker"]]:
            if f <= r["date"] and (not l or r["date"] <= l):
                px[p][r["date"]] = (float(r["closeunadj"] or 0), float(r["closeadj"] or 0))
    return px


def c5_prices(mapped: dict, px: dict, delisted: set) -> list:
    day_count = Counter(d for p in px.values() for d in p)
    days = sorted(d for d, n in day_count.items() if n >= 300)  # sessions: most members priced
    have = need = have_d = need_d = 0
    for p, spans in mapped.items():
        for a, b in spans:
            lo = bisect.bisect_left(days, a)
            hi = bisect.bisect_left(days, b) if b else len(days)
            for d in days[lo:hi]:
                hit = d in px.get(p, {})
                have += hit
                need += 1
                if p in delisted:
                    have_d += hit
                    need_d += 1
    share, share_d = have / max(need, 1), have_d / max(need_d, 1)
    save_private("members.json", {p: spans for p, spans in mapped.items()})
    record("C5", {"member_days": need, "priced_share": round(share, 4),
                  "delisted_member_days": need_d, "delisted_priced_share": round(share_d, 4)},
           passed=share >= 0.99 and share_d >= 0.99)
    return days


def c6_delistings(mapped: dict, tmap: dict) -> None:
    perma_tickers = defaultdict(set)
    for t, lst in tmap.items():
        for f, l, p, isdel in lst:
            if p in mapped and isdel == "Y":
                perma_tickers[p].add(t)
    acts = defaultdict(set)
    for r in rows("actions"):
        acts[r["ticker"]].add(r["action"])
    kinds, with_delist, with_value = Counter(), 0, 0
    acquired = 0
    for p, tickers in perma_tickers.items():
        seen = set().union(*(acts.get(t, set()) for t in tickers))
        hit = seen & DELIST
        kinds.update(hit or {"none"})
        with_delist += bool(hit)
        if {"acquisitionby", "mergerfrom"} & seen:
            acquired += 1
            with_value += bool(seen & ACQ_VALUE)
    n = len(perma_tickers)
    record("C6", {"delisted_members": n, "with_delisting_action": round(with_delist / max(n, 1), 4),
                  "action_kinds": dict(kinds), "acquired": acquired,
                  "acquired_with_value": round(with_value / max(acquired, 1), 4)},
           passed=with_delist / max(n, 1) >= 0.95)


def c7_returns(mapped: dict, px: dict, tmap: dict) -> None:
    """Rebuilt return (AD-06) vs the closeadj return, on member days; splits and spinoffs counted apart."""
    p_tickers = defaultdict(set)
    for t, lst in tmap.items():
        for _, _, p, _ in lst:
            if p in mapped:
                p_tickers[p].add(t)
    t_perma = {t: p for p, ts in p_tickers.items() for t in ts}
    split, div, spin = defaultdict(dict), defaultdict(dict), defaultdict(set)
    for r in rows("actions"):
        p = t_perma.get(r["ticker"])
        if p is None or not r["value"]:
            continue
        if r["action"] == "split":
            split[p][r["date"]] = split[p].get(r["date"], 1.0) * float(r["value"])
        elif r["action"] == "dividend":
            div[p][r["date"]] = div[p].get(r["date"], 0.0) + float(r["value"])
        elif r["action"].startswith("spinoff"):
            spin[p].add(r["date"])
    ok = n = spin_days = 0
    worst = Counter()
    for p, series in px.items():
        dates = sorted(series)
        later = sorted(split[p].items())
        for prev, d in zip(dates, dates[1:]):
            (u0, a0), (u1, a1) = series[prev], series[d]
            if not (u0 and a0 and u1 and a1):
                continue
            if d in spin[p]:
                spin_days += 1
                continue
            s = split[p].get(d, 1.0)
            # Sharadar dividends are split-adjusted to today's shares: undo splits after the ex-date
            undo = 1.0
            for sd, sv in later:
                if sd > d:
                    undo *= sv
            r_rebuilt = (u1 * s + div[p].get(d, 0.0) * undo) / u0 - 1
            r_adj = a1 / a0 - 1
            n += 1
            gap = abs(r_rebuilt - r_adj)
            ok += gap <= 1e-4
            worst["split_day" if d in split[p] else "dividend_day" if d in div[p] else "plain_day"] += gap > 1e-4
    share = ok / max(n, 1)
    record("C7", {"days": n, "within_1bp": round(share, 4), "misses_by_kind": dict(worst),
                  "spinoff_days_skipped": spin_days}, passed=share >= 0.99)


# ---- step 3: incremental update and revision filter (C9) ----

def c9_update(mapped_current: list) -> None:
    t0 = time.time()
    since = (dt.date.today() - dt.timedelta(days=7)).isoformat()
    n_rows = 0
    for i in range(0, len(mapped_current), 100):
        _, body, _ = request("/data/stocks", {"ticker": ",".join(mapped_current[i:i + 100]),
                                              "from": since, "format": "json"})
        n_rows += len(json.loads(body)["data"])
    _, body, _ = request("/data/stocks", {"lastupdated.gte": since, "format": "json", "limit": 10})
    revised = len(json.loads(body)["data"])
    minutes = round((time.time() - t0) / 60, 2)
    record("C9", {"minutes": minutes, "rows_last_7_days": n_rows, "lastupdated_filter_rows": revised,
                  "http": dict(calls)}, passed=minutes <= 5 and revised > 0)


def main() -> None:
    step = sys.argv[1] if len(sys.argv) > 1 else ""
    load_env(["SHARADAR_API_KEY"])
    if step == "bulk":
        c8_bulk()
    elif step == "checks":
        intervals, snaps = membership()
        c3_membership(intervals, snaps)
        tmap = ticker_map()
        mapped = c4_mapping(intervals, tmap)
        delisted = {p for lst in tmap.values() for _, _, p, isdel in lst if isdel == "Y" and p in mapped}
        px = load_prices(set(mapped), tmap)
        c5_prices(mapped, px, delisted)
        c6_delistings(mapped, tmap)
        c7_returns(mapped, px, tmap)
    elif step == "update":
        current = sorted({r["ticker"] for r in rows("sp500") if r["action"] == "current"})
        c9_update(current)
    else:
        sys.exit("usage: python3 probe.py bulk|checks|update")
    write_evidence(runner="user", env="production", base_url=BASE)


if __name__ == "__main__":
    main()

