"""PB-02 user checks: EODHD Historian on the researcher's key, against PB-01's Sharadar files.

Needs PB-01's `bulk` and `checks` steps first: it reads ../PB-01-sharadar-coverage/out/ (tickers.csv,
stocks.csv, members.json). Run:  python3 probe.py fetch   then   python3 probe.py checks
Raw EODHD responses stay in out/eod/ (licensed data, never committed).
"""
from __future__ import annotations

import csv
import json
import os
import sys
import urllib.error
import urllib.request
from collections import Counter, defaultdict
from pathlib import Path

from probe_kit import load_env, private, record, write_evidence

BASE = os.environ.get("EODHD_BASE_URL", "https://eodhd.com/api")
PB01 = Path(__file__).resolve().parent.parent / "PB-01-sharadar-coverage" / "out"
SINCE = "2010-01-01"
calls = Counter()


def get(path: str, params: str = "") -> list | None:
    url = f"{BASE}{path}?api_token={os.environ['EODHD_API_KEY']}&fmt=json{params}"
    try:
        with urllib.request.urlopen(url, timeout=120) as r:
            calls[r.status] += 1
            return json.loads(r.read())
    except urllib.error.HTTPError as e:
        calls[e.code] += 1
        if e.code == 404:
            return None
        sys.exit(f"HTTP {e.code} on {path.split('/')[1]}")  # never the URL: it carries the key


def members() -> dict:
    """permaticker -> {"tickers": [...], "spans": [[start, end|None], ...]} for members since 2010."""
    spans = json.loads((PB01 / "members.json").read_text())
    tick = defaultdict(set)
    with open(PB01 / "tickers.csv", newline="") as f:
        for r in csv.DictReader(f):
            if r["table"] == "SEP" and r["permaticker"] in spans:
                tick[r["permaticker"]].update({r["ticker"], *(r["relatedtickers"] or "").split()})
    return {p: {"tickers": sorted(tick[p]), "spans": s} for p, s in spans.items()
            if any(b is None or b >= SINCE for _, b in s)}


def c3_symbols(m: dict) -> dict:
    listed = {r["Code"] for r in get("/exchange-symbol-list/US") or []}
    delisted = {r["Code"] for r in get("/exchange-symbol-list/US", "&delisted=1") or []}
    chosen, kinds = {}, Counter()
    for p, info in m.items():
        for t in info["tickers"]:
            code = t.replace(".", "-")
            if code in listed or code in delisted:
                chosen[p] = code
                kinds["listed" if code in listed else "delisted"] += 1
                break
        else:
            kinds["unmatched"] += 1
    (private("symbols.json")).write_text(json.dumps(chosen))
    share = len(chosen) / max(len(m), 1)
    record("C3", {"securities": len(m), "matched_share": round(share, 4), "kinds": dict(kinds)},
           passed=None, note="judged with C4: coverage is what DATA-06 needs")
    return chosen


def fetch(symbols: dict) -> None:
    folder = private("eod")
    folder.mkdir(mode=0o700, exist_ok=True)
    for p, code in symbols.items():
        target = folder / f"{p}.json"
        if target.exists():
            continue
        eod = get(f"/eod/{code}.US", f"&from={SINCE}") or []
        div = get(f"/div/{code}.US", f"&from={SINCE}") or []
        spl = get(f"/splits/{code}.US", f"&from={SINCE}") or []
        target.write_text(json.dumps({"eod": eod, "div": div, "splits": spl}))
        os.chmod(target, 0o600)
    record("C8", {"calls": sum(calls.values()), "http": dict(calls)},
           passed=sum(calls.values()) <= 20_000 and not calls.get(429))


def sharadar(m: dict, symbols: dict) -> dict:
    """{perma: {date: (closeunadj, closeadj)}} on member days since 2010, from PB-01's stocks.csv."""
    by_ticker = {t: p for p in symbols for t in m[p]["tickers"]}
    px = defaultdict(dict)
    with open(PB01 / "stocks.csv", newline="") as f:
        for r in csv.DictReader(f):
            p = by_ticker.get(r["ticker"])
            if p and r["date"] >= SINCE and any(a <= r["date"] and (b is None or r["date"] < b)
                                                for a, b in m[p]["spans"]):
                px[p][r["date"]] = (float(r["closeunadj"] or 0), float(r["closeadj"] or 0))
    return px


def checks(m: dict, symbols: dict) -> None:
    px = sharadar(m, symbols)
    total_by_year, hit_by_year = Counter(), Counter()
    for p, days in px.items():
        for d in days:
            total_by_year[d[:4]] += 1
    close_ok = close_n = ret_ok = ret_n = checkable = 0
    old_delisted_with_actions = old_delisted = 0
    for p, code in symbols.items():
        path = private("eod") / f"{p}.json"
        if not path.exists():
            continue
        v = json.loads(path.read_text())
        eod = {r["date"]: r for r in v["eod"]}
        div = {r["date"]: float(r.get("unadjustedValue") or r["value"]) for r in v["div"]}
        spl = {}
        for r in v["splits"]:
            new, old = r["split"].split("/")
            spl[r["date"]] = float(new) / float(old)
        mine = px.get(p, {})
        dates = sorted(set(mine) & set(eod))
        for d in dates:
            hit_by_year[d[:4]] += 1
            u = mine[d][0]
            if u:
                close_n += 1
                close_ok += abs(eod[d]["close"] / u - 1) <= 0.005
        has_actions = bool(v["div"] or v["splits"])
        last = max(eod, default="")
        if last and last < "2018-01-01":
            old_delisted += 1
            old_delisted_with_actions += has_actions
        if not has_actions:
            continue
        checkable += len(dates)
        for a, b in zip(dates, dates[1:]):
            e0, e1 = eod[a]["close"], eod[b]["close"]
            s0, s1 = mine[a][1], mine[b][1]
            if not (e0 and s0):
                continue
            rebuilt = (e1 * spl.get(b, 1.0) + div.get(b, 0.0)) / e0 - 1
            ret_n += 1
            ret_ok += abs(rebuilt - (s1 / s0 - 1)) <= 1e-4
    cover = {y: round(hit_by_year[y] / total_by_year[y], 4) for y in sorted(total_by_year)}
    total = sum(total_by_year.values())
    record("C4", {"coverage_by_year": cover}, passed=min(cover.values(), default=0) >= 0.50)
    record("C5", {"days": close_n, "within_0.5pct": round(close_ok / max(close_n, 1), 4)},
           passed=close_ok / max(close_n, 1) >= 0.99)
    record("C6", {"days": ret_n, "within_1bp": round(ret_ok / max(ret_n, 1), 4)},
           passed=ret_ok / max(ret_n, 1) >= 0.99)
    record("C7", {"pre2018_delisted": old_delisted, "with_actions": old_delisted_with_actions,
                  "return_checkable_share": round(checkable / max(total, 1), 4)},
           passed=checkable / max(total, 1) >= 0.50)


def main() -> None:
    step = sys.argv[1] if len(sys.argv) > 1 else ""
    load_env(["EODHD_API_KEY"])
    m = members()
    if step == "fetch":
        fetch(c3_symbols(m))
    elif step == "checks":
        checks(m, json.loads(private("symbols.json").read_text()))
    else:
        sys.exit("usage: python3 probe.py fetch|checks")
    write_evidence(runner="user", env="production", base_url=BASE)


if __name__ == "__main__":
    main()

